import { anyApi } from "convex/server";
import type { FunctionReference } from "convex/server";
import type { DashboardSummary } from "../../convex/lib/contracts";
import type { ServiceStatus } from "../../convex/summary";

/**
 * `convex/summary.ts` exists on disk and is frozen against
 * `convex/lib/contracts.ts`, but `convex/_generated/api.d.ts` is a build
 * artifact regenerated by `npx convex dev`/`convex codegen` (both talk to
 * the deployment) and is not one of this unit's owned files — a concurrent
 * unit owns it, and as of this run it does not list the `summary` module
 * yet (only `library`). `convex/publication.ts` hit the identical gap for
 * `internal.publication.applyUpdate` and solved it the same way: reference
 * the function by name via `anyApi` (convex/server) instead of the
 * generated `api` object. This resolves to the exact same function
 * reference at runtime — `useQuery(summaryQuery, {})` behaves exactly like
 * `useQuery(api.summary.summary, {})` would. Swap these two for
 * `api.summary.summary` / `api.summary.health` once codegen has run and
 * picked up the module; nothing else about the call sites needs to change.
 *
 * The explicit `FunctionReference` cast is what keeps every consumer of
 * these two typed against `DashboardSummary` / `ServiceStatus[]` (from
 * `convex/lib/contracts.ts` / `convex/summary.ts`) instead of falling back
 * to `any`, so a shape mismatch here still fails `tsc --noEmit` like it
 * would through the generated `api` object.
 */
// `now` is REQUIRED on both (convex/summary.ts's own validators: a query may
// never read the wall clock itself, so the caller must supply it and refresh
// it — see that file's comment on `summary`/`health`). This used to be typed
// as `Record<string, never>` / `{ now?: number }`, which let src/library/
// Library.tsx call both with `{}` and pass tsc while Convex would reject the
// missing required arg at runtime; fixed together with that call site.
// SAFETY: `anyApi.summary.summary` is typed as `FunctionReference<any, any>`
// because `convex/_generated/api.d.ts` has not picked up `convex/summary.ts`
// yet (see the module comment above); the `any` type parameters make this a
// single, non-widening assertion to the reference's real, frozen contract.
export const summaryQuery = anyApi.summary.summary as FunctionReference<
  "query",
  "public",
  { now: number },
  DashboardSummary
>;

// SAFETY: same as `summaryQuery` above — `anyApi.summary.health` is
// `FunctionReference<any, any>` until codegen picks up `convex/summary.ts`.
export const healthQuery = anyApi.summary.health as FunctionReference<
  "query",
  "public",
  { now: number },
  ServiceStatus[]
>;
